ALTER TABLE "service_sessions" ADD CONSTRAINT "service_sessions_close_state_check" CHECK (("service_sessions"."status" = 'OPEN' AND "service_sessions"."closed_at" IS NULL AND "service_sessions"."closed_by" IS NULL) OR ("service_sessions"."status" IN ('CLOSED', 'CANCELLED') AND "service_sessions"."closed_at" IS NOT NULL AND "service_sessions"."closed_by" IS NOT NULL));--> statement-breakpoint
ALTER TABLE "session_items" ADD CONSTRAINT "session_items_removal_state_check" CHECK (("session_items"."status" = 'ACTIVE' AND "session_items"."removed_at" IS NULL AND "session_items"."removed_by" IS NULL) OR ("session_items"."status" = 'REMOVED' AND "session_items"."removed_at" IS NOT NULL AND "session_items"."removed_by" IS NOT NULL));